<?php
namespace App\Import\Importer;
use App\Entity\Review;use App\Import\DTO\ReviewImportDto;use App\Repository\OrderRepository;use App\Repository\ProductRepository;use App\Repository\ReviewRepository;use App\Repository\UserRepository;use Doctrine\ORM\EntityManagerInterface;
final readonly class ReviewImporter implements DataImporterInterface {
 public function __construct(private ReviewRepository $reviews,private UserRepository $users,private ProductRepository $products,private OrderRepository $orders,private EntityManagerInterface $em){}
 public function supports(string $type):bool{return 'reviews'===$type;}
 public function import(object $dto):ImportOutcome {assert($dto instanceof ReviewImportDto);$user=$this->users->findOneBy(['externalRef'=>$dto->userExternalRef]);if(!$user)throw new \DomainException(sprintf('Unknown user "%s".',$dto->userExternalRef));$product=$this->products->findOneBy(['externalRef'=>$dto->productExternalRef]);if(!$product)throw new \DomainException(sprintf('Unknown product "%s".',$dto->productExternalRef));if(!$this->orders->hasUserPurchasedProduct($user,$product))throw new \DomainException('User has no verified purchase for this product.');$review=$this->reviews->findOneBy(['externalRef'=>$dto->externalRef]);if($review&&($review->getUser()!==$user||$review->getProduct()!==$product))throw new \DomainException('External reference belongs to another user/product pair.');$pair=$this->reviews->findOneByUserAndProduct($user,$product);if($pair&&$pair!==$review)throw new \DomainException('User already reviewed this product with another external reference.');$out=$review?ImportOutcome::Updated:ImportOutcome::Created;$review??=(new Review($user,$product,$dto->rating,$dto->createdAt))->setExternalRef($dto->externalRef);$review->setRating($dto->rating)->setComment($dto->comment);$this->em->persist($review);$this->em->flush();return $out;}
}
